Which set of inequalities defines the shaded region of intersection?
[tikz]
\begin{tikzpicture}[every node/.style={font=\large}, scale=0.65]
\fill[blue!14] (-1,-1) -- (-1,3) -- (3,3) -- cycle;
\draw[gray!30,very thin] (-3,-3) grid (5,5);
\draw[->] (-3.3,0) -- (5.5,0) node[right] {$x$};
\draw[->] (0,-3.3) -- (0,5.5) node[above] {$y$};
\node[below,font=\scriptsize] at (-2,-0.05) {$-2$};
\node[below,font=\scriptsize] at (-1,-0.05) {$-1$};
\node[below,font=\scriptsize] at (1,-0.05) {$1$};
\node[below,font=\scriptsize] at (2,-0.05) {$2$};
\node[below,font=\scriptsize] at (3,-0.05) {$3$};
\node[below,font=\scriptsize] at (4,-0.05) {$4$};
\node[left,font=\scriptsize] at (-0.05,-2) {$-2$};
\node[left,font=\scriptsize] at (-0.05,-1) {$-1$};
\node[left,font=\scriptsize] at (-0.05,1) {$1$};
\node[left,font=\scriptsize] at (-0.05,2) {$2$};
\node[left,font=\scriptsize] at (-0.05,3) {$3$};
\node[left,font=\scriptsize] at (-0.05,4) {$4$};
\draw[blue!70!black,thick,dashed,<->] (-1,-3) -- (-1,5);
\draw[blue!70!black,thick,dashed,<->] (-3,3) -- (5,3);
\draw[blue!70!black,thick,dashed,<->] (-3,-3) -- (5,5);
\node at (0.6,2) {$R$};
\end{tikzpicture}
[/tikz]
